-- Supabase Seed Especial para Teste de Homologação da Chiara (Studio Aurora)
-- Versão: v0.1.1

-- 1. Inserir Usuário Administrador de Plataforma do Studio Aurora
ON CONFLICT (user_id) DO UPDATE SET global_role = EXCLUDED.global_role, status = EXCLUDED.status;

-- 2. Inserir Organização Studio Aurora
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, settings_json = EXCLUDED.settings_json;

-- 3. Inserir Membro da Organização
ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role, status = EXCLUDED.status;

-- 4. Inserir Assistente Virtual Chiara (Digital Employee)
ON CONFLICT (id) DO NOTHING;

-- 5. Inserir Profissionais
ON CONFLICT (id) DO NOTHING;

-- 6. Inserir Serviços com Buffer de 15 Minutos
ON CONFLICT (id) DO NOTHING;

-- 7. Vínculos Profissional <-> Serviço
ON CONFLICT (professional_id, service_id) DO NOTHING;

-- 8. Regras de Disponibilidade (Seg-Qui 09:00-18:00; Sex 09:00-17:00)
ON CONFLICT DO NOTHING;

-- 9. Base de Clientes Fictícios (10 Clientes do Teste)
ON CONFLICT (organization_id, phone_normalized) DO UPDATE SET first_name = EXCLUDED.first_name, last_name = EXCLUDED.last_name;

-- 10. Regras do Escritório
ON CONFLICT (organization_id) DO NOTHING;

-- 11. Agenda Fictícia (32 Agendamentos em Agosto de 2026: AG-101 a AG-132)
ON CONFLICT (id) DO NOTHING;
